parsed.prompt_body:
CREATE a new table addresses with columns id INT PRIMARY KEY, user_id INT FOREIGN KEY REFERENCES users(id), street TEXT, city TEXT, state TEXT, zip TEXT, is_primary BOOL;
ADD a column shipping_address_id INT to the orders table as a FOREIGN KEY referencing addresses(id);
UPDATE existing orders to associate each with a primary address after backfill;
ENSURE constraints maintain referential integrity between users, addresses, and orders;
GENERATE a backfill script that inserts a default address for each user using placeholder data for street, city, state, zip, and sets is_primary TRUE;
PROVIDE a validation query that selects any orders where shipping_address_id does NOT exist in addresses;
